        arab: "\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0646\u064e",
