      Ayah(
        numberInSurah: 62,
        numberInQuran: 2735,
        juz: 18,
        page: 346,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u064a\u064e\u0646\u0637\u0650\u0642\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa laa nukallifu nafsan illaa wus'ahaa wa ladainaa kitaabuny yantiqu bilhaqqi w ahum la yuzlamoon",
        translation: "Dan Kami tidak membebani seseorang melainkan menurut kesanggupannya, dan pada Kami ada suatu catatan yang menuturkan dengan sebenarnya, dan mereka tidak dizalimi (dirugikan).",
        shortTafsir: "Para pendurhaka yang disebut pada ayat sebelumnya boleh jadi menganggap bahwa ajaran agama sangat memberatkan. Menyanggah anggapan ini Allah berfirman, \u201cDan Kami tidak membebani seseorang dengan amalan-amalan ibadah melainkan menurut kesanggupannya, maka tidak sewajarnya bila seseorang merasa tidak mampu; dan pada Kami ada suatu catatan yang menuturkan dengan sebenarnya apa saja yang dilakukan oleh manusia, dan mereka tidak dizalimi atau dirugikan dengan bertambahnya dosa atau berkurangnya pahala. Allah tidak akan pernah berbuat zalim kepada manusia, tetapi manusialah yang menzalimi diri sendiri (Lihat juga: Surah Y\u00f9nus/10: 44).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2735",
      ),
      Ayah(
        numberInSurah: 63,
        numberInQuran: 2736,
        juz: 18,
        page: 346,
        arab: "\u0628\u064e\u0644\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0645\u0652\u0631\u064e\u0629\u064d \u0645\u0651\u0650\u0646\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064c \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0645\u0650\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Bal quloobuhum fee ghamratim min haazaa wa lahum a'maalum min dooni zaalika hum lahaa 'aamiloon",
        translation: "Tetapi, hati mereka (orang-orang kafir) itu dalam kesesatan dari (memahami Al-Qur'an) ini, dan mereka mempunyai (kebiasaan banyak mengerjakan) perbuatan-perbuatan lain (buruk) yang terus mereka kerjakan.",
        shortTafsir: "Tetapi\u00a0meski ajaran Allah demikian jelas dan mudah, orang-orang kafir itu tetap durhaka sehingga\u00a0hati mereka itu dalam kesesatan\u00a0terkait hakikat yang Kami sampaikan\u00a0ini, dan mereka mempunyai\u00a0kebiasaan melakukan\u00a0perbuatan-perbuatan lain\u00a0yang buruk\u00a0yang terus mereka kerjakan.\u00a0Mereka melampaui batas dalam melakukannya sehingga mereka pantas menerima siksa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2736",
      ),
      Ayah(
        numberInSurah: 64,
        numberInQuran: 2737,
        juz: 18,
        page: 346,
        arab: "\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062c\u0652\u0623\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Hattaaa izaaa akhznaa mutrafeehim bil'azaabi izaa hum yaj'aroon",
        translation: "Sehingga apabila Kami timpakan siksaan kepada orang-orang yang hidup bermewah-mewah di antara mereka, seketika itu mereka berteriak-teriak meminta tolong.",
        shortTafsir: "Mereka terus-menerus larut dalam kedurhakaan, sehingga apabila Kami timpakan siksaan kepada orang-orang yang hidup bermewah-mewah di antara mereka dan para pengikut mereka, seketika itu mereka berteriak-teriak meminta tolong dengan penuh kehinaan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2737",
      ),
      Ayah(
        numberInSurah: 65,
        numberInQuran: 2738,
        juz: 18,
        page: 346,
        arab: "\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0623\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Laa taj'arul yawma innakum minnaa laa tunsaroon",
        translation: "Janganlah kamu berteriak-teriak meminta tolong pada hari ini! Sungguh, kamu tidak akan mendapat pertolongan dari Kami.",
        shortTafsir: "Menolak permintaan tolong mereka, Allah berfirman, \u201cJanganlah kamu berteriak-teriak meminta tolong pada hari ini! Sungguh, kamu tidak akan mendapat pertolongan dari Kami\u00a0dan tidak pula dapat menghindari siksa Kami.\u00a0Sesungguhnya ayat-ayat-Ku,\u00a0yaitu Al-Qur\u2019an,\u00a0selalu dibacakan kepada kamu, wahai para pendurhaka, supaya kamu merenungi dan mengimaninya,\u00a0tetapi kamu selalu berpaling ke belakang\u00a0dan enggan mendengarkannya; kamu berpaling\u00a0dengan menyombong\u00adkan diri\u00a0atas kaum mukmin\u00a0dan mengucapkan perkataan-perkataan keji terhadapnya, yaitu Al-Qur\u2019an,\u00a0pada waktu kamu bercakap-cakap pada malam hari.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2738",
      ),
