      ),
      Ayah(
        numberInSurah: 67,
        numberInQuran: 2740,
        juz: 18,
        page: 346,
        arab: "\u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650 \u0633\u064e\u0627\u0645\u0650\u0631\u064b\u0627 \u062a\u064e\u0647\u0652\u062c\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Mustakbireena bihee saamiran tahjuroon",
        translation: "dengan menyombongkan diri dan mengucapkan perkataan-perkataan keji terhadapnya (Al-Qur'an) pada waktu kamu bercakap-cakap pada malam hari.",
        shortTafsir: "Menolak permintaan tolong mereka, Allah berfirman, \u201cJanganlah kamu berteriak-teriak meminta tolong pada hari ini! Sungguh, kamu tidak akan mendapat pertolongan dari Kami\u00a0dan tidak pula dapat menghindari siksa Kami.\u00a0Sesungguhnya ayat-ayat-Ku,\u00a0yaitu Al-Qur\u2019an,\u00a0selalu dibacakan kepada kamu, wahai para pendurhaka, supaya kamu merenungi dan mengimaninya,\u00a0tetapi kamu selalu berpaling ke belakang\u00a0dan enggan mendengarkannya; kamu berpaling\u00a0dengan menyombong\u00adkan diri\u00a0atas kaum mukmin\u00a0dan mengucapkan perkataan-perkataan keji terhadapnya, yaitu Al-Qur\u2019an,\u00a0pada waktu kamu bercakap-cakap pada malam hari.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2740",
      ),
      Ayah(
        numberInSurah: 68,
        numberInQuran: 2741,
        juz: 18,
        page: 346,
        arab: "\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062f\u0651\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0623\u064e\u0645\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Afalam yaddabbarrul qawla am jaaa'ahum maa lam yaati aabaaa'ahumul awwaleen",
        translation: "Maka tidakkah mereka menghayati firman (Allah), atau adakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka terdahulu?",
        shortTafsir: "Maka keberpalingan dan perlakukan para pendurhaka itu kepada ayat-ayat Kami sungguh keterlaluan. Tidakkah mereka menggunakan akalnya sehingga dapat menghayati firman Kami, ataukah mereka mendustakan rasul dengan alasan telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka terdahulu, yaitu risalah kenabian yang tidak dikenal oleh leluhur mereka? Jelas bukan itu alasannya! Risalah Nabi Muhamamd sama dengan risalah nabi-nabi terdahulu (Lihat juga: Surah al-Anbiy\u00e0\u2019/21: 25). Ataukah\u00a0mereka ingkar dengan dalih bahwa mereka tidak mengenal Rasul mereka, yaitu Nabi Muhammad, karena itu mereka mengingkarinya? Ini pun bukanlah alasan yang dapat diterima karena mereka mengenal dengan baik Nabi Muhammad, bahkan mereka mengakui integritasnya dengan menggelarinya \u201cal-Amin\u201d? Atau\u00a0apakah mereka menolak dakwah Nabi Muhamamd dengan berkata, \u201cOrang itu gila!\u201d? Sungguh, tuduhan itu tidak masuk akal karena mereka tahu pasti Nabi Muhammad adalah orang yang paling lurus akalnya. Sebenarnya, pangkal penolakan adalah karena dia telah datang membawa kebenaran, yaitu Al-Qur\u2019an, kepada mereka, tetapi kebanyakan mereka membenci kebenaran karena bertentangan dengan hawa nafsu dan syahwat mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2741",
      ),
      Ayah(
        numberInSurah: 69,
        numberInQuran: 2742,
        juz: 18,
        page: 346,
        arab: "\u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0645\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Am lam ya'rifoo Rasoolahum fahum lahoo munkiroon",
        translation: "Ataukah mereka tidak mengenal Rasul mereka (Muhammad), karena itu mereka mengingkarinya?",
        shortTafsir: "Maka\u00a0keberpalingan dan perlakukan para pendurhaka itu kepada ayat-ayat Kami sungguh keterlaluan.\u00a0Tidakkah mereka\u00a0menggunakan akalnya sehingga dapat\u00a0menghayati firman\u00a0Kami,\u00a0ataukah\u00a0mereka mendustakan rasul dengan alasan\u00a0telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka terdahulu,\u00a0yaitu risalah kenabian yang tidak dikenal oleh leluhur mereka? Jelas bukan itu alasannya! Risalah Nabi Muhamamd sama dengan risalah nabi-nabi terdahulu (Lihat juga: Surah al-Anbiy\u00e0\u2019/21: 25).\u00a0Ataukah\u00a0mereka ingkar dengan dalih bahwa\u00a0mereka tidak mengenal Rasul mereka,\u00a0yaitu Nabi Muhammad,\u00a0karena itu mereka mengingkarinya?\u00a0Ini pun bukanlah alasan yang dapat diterima karena mereka mengenal dengan baik Nabi Muhammad, bahkan mereka mengakui integritasnya dengan menggelarinya \u201cal-Amin\u201d?\u00a0Atau\u00a0apakah\u00a0mereka\u00a0menolak dakwah Nabi Muhamamd dengan\u00a0berkata, \u201cOrang itu gila!\u201d? Sungguh, tuduhan itu tidak masuk akal karena mereka tahu pasti Nabi Muhammad adalah orang yang paling lurus akalnya. Sebenarnya, pangkal penolakan adalah karena\u00a0dia telah datang membawa kebenaran,\u00a0yaitu Al-Qur\u2019an,\u00a0kepada mereka, tetapi kebanyakan mereka membenci kebenaran\u00a0karena bertentangan dengan hawa nafsu dan syahwat mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2742",
      ),
      Ayah(
        numberInSurah: 70,
        numberInQuran: 2743,
        juz: 18,
        page: 346,
        arab: "\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u062c\u0650\u0646\u0651\u064e\u0629\u064c \u06da \u0628\u064e\u0644\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",
