      Ayah(
        numberInSurah: 84,
        numberInQuran: 2757,
        juz: 18,
        page: 347,
        arab: "\u0642\u064f\u0644 \u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Qul limanil ardu wa man feehaaa in kuntum ta'lamoon",
        translation: "Katakanlah (Muhammad), \u201cMilik siapakah bumi, dan semua yang ada di dalamnya, jika kamu mengetahui?\u201d",
        shortTafsir: "\u201cWahai Nabi Muhammad! Katakanlah kepada orang-orang yang keras kepala dan mengingkari hari Kiamat, \"Milik siapakah bumi dan semua yang ada di dalamnya, jika kamu mengetahui?\" Pasti mereka akan menjawab dengan spontan, \"Milik Allah.\" Katakanlah, \"Jika demikian maka apakah kamu tidak ingat dan sadar bahwa Tuhan yang memiliki sifat dan kekuasaan demikian pasti mudah bagi-Nya untuk membangkitkan manusia setelah mati?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2757",
      ),
