      Ayah(
        numberInSurah: 88,
        numberInQuran: 2761,
        juz: 18,
        page: 347,
        arab: "\u0642\u064f\u0644\u0652 \u0645\u064e\u0646 \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062c\u0650\u064a\u0631\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0631\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Qul mam bi yadihee malakootu kulli shai'inw wa Huwa yujeeru wa laa yujaaru 'alaihi in kuntum ta'lamoon",
        translation: "Katakanlah, \u201cSiapakah yang di tangan-Nya berada kekuasaan segala sesuatu. Dia melindungi, dan tidak ada yang dapat dilindungi dari (azab-Nya), jika kamu mengetahui?\u201d",
        shortTafsir: "Wahai Nabi Muhammad! pengingkaran orang-orang kafir itu sama sekali tidak berdasar, maka katakanlah kepada mereka, \u201cSiapakah yang di tangan-Nya berada kekuasaan segala sesuatu. Dia melindungi, memelihara, dan memenangkan siapa yang dikehendaki-Nya, dan tidak ada yang dapat dilindungi dari azab-Nya apabila Allah sudah menetapkan siksa baginya? Jawablah pertanyaan itu jika kamu mengetahui?\u201d Mereka pasti akan menjawab, \u201cMilik Allah.\u201d Maka, jelas sudah apa yang sebenarnya ada di benak mereka. Katakanlah lagi, \u201cBila demikian maka bagaimana kamu sampai tertipu oleh hawa nafsu dan bujukan setan untuk mendurhakai-Nya dan meyakini hari Kebangkitan tidak akan terjadi?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2761",
      ),
      Ayah(
        numberInSurah: 89,
        numberInQuran: 2762,
        juz: 18,
        page: 347,
        arab: "\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0633\u0652\u062d\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Sa yaqooloona lillaah; qul fa annaa tus haroon",
        translation: "Mereka akan menjawab, \u201c(Milik) Allah.\u201d Katakanlah, \u201c(Kalau demikian), maka bagaimana kamu sampai tertipu?\u201d",
        shortTafsir: "Wahai Nabi Muhammad! pengingkaran orang-orang kafir itu sama sekali tidak berdasar, maka\u00a0katakanlah\u00a0kepada mereka, \u201cSiapakah yang di tangan-Nya berada kekuasaan segala sesuatu. Dia melindungi, memelihara, dan memenangkan siapa yang dikehendaki-Nya,\u00a0dan tidak ada yang dapat dilindungi dari\u00a0azab-Nya apabila Allah sudah menetapkan siksa baginya? Jawablah pertanyaan itu\u00a0jika kamu mengetahui?\u201d Mereka\u00a0pasti\u00a0akan menjawab, \u201cMilik\u00a0Allah.\u201d Maka, jelas sudah apa yang sebenarnya ada di benak mereka.\u00a0Katakanlah\u00a0lagi, \u201cBila demikian\u00a0maka bagaimana kamu sampai tertipu\u00a0oleh hawa nafsu dan bujukan setan untuk mendurhakai-Nya dan meyakini hari Kebangkitan tidak akan terjadi?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2762",
      ),
      Ayah(
        numberInSurah: 90,
        numberInQuran: 2763,
        juz: 18,
        page: 348,
        arab: "\u0628\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Bal atainaahum bil haqqi wa innahum lakaaziboon",
        translation: "Padahal Kami telah membawa kebenaran kepada mereka, tetapi mere-ka benar-benar pendusta.",
        shortTafsir: "Padahal, Kami melalui para rasul yang Kami utus telah membawa kebenaran yang mutlak, sempurna, dan tidak mengandung keraguan apalagi kebatilan, kepada mereka, yaitu orang-orang kafir itu, tetapi mereka benar-benar pendusta.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2763",
      ),
      Ayah(
        numberInSurah: 91,
        numberInQuran: 2764,
        juz: 18,
        page: 348,
        arab: "\u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0648\u064e\u0644\u064e\u062f\u064d \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u06da \u0625\u0650\u0630\u064b\u0627 \u0644\u0651\u064e\u0630\u064e\u0647\u064e\u0628\u064e \u0643\u064f\u0644\u0651\u064f \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u0628\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",
        transliteration: "Mat takhazal laahu minw waladinw wa maa kaana ma'ahoo min ilaah; izal lazahaba kullu ilaahim bimaa khalaqa wa la'alaa ba'duhum 'alaa ba'd; Subhaannal laahi 'ammaa yasifoon",
        translation: "Allah tidak mempunyai anak, dan tidak ada tuhan (yang lain) bersama-Nya, (sekiranya tuhan banyak), maka masing-masing tuhan itu akan membawa apa (makhluk) yang diciptakannya, dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain. Mahasuci Allah dari apa yang mereka sifatkan itu,",
        shortTafsir: "Salah satu kedustaan kaum kafir terhadap Allah adalah menuduh Allah memiliki sekutu dan anak; suatu tuduhan yang Allah bantah melalui ayat ini.\u00a0Allah tidak mempunyai anak, dan tidak ada tuhan\u00a0pencipta dan penguasa alam raya yang lain\u00a0bersama-Nya. Sekiranya tuhan lebih dari satu,\u00a0maka masing-masing tuhan itu\u00a0pasti\u00a0akan membawa apa,\u00a0yakni makhluk,\u00a0yang diciptakannya\u00a0untuk diaturnya sendiri,\u00a0dan sebagian dari tuhan-tuhan\u00a0yang kuat\u00a0akan mengalahkan sebagian\u00a0tuhan\u00a0yang\u00a0lain yang lebih lemah. Dia berbuat demikian untuk memperluas kekuasaan-Nya, seperti halnya yang terjadi pada para penguasa di dunia.\u00a0Mahasuci Allah dari apa yang mereka sifatkan itu.\u00a0Sifat-sifat yang kaum kafir lekatkan kepada Allah bertentangan dengan kebenaran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2764",
      ),
      Ayah(
        numberInSurah: 92,
        numberInQuran: 2765,
        juz: 18,
        page: 348,
        arab: "\u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",
        transliteration: "'Aalimil Ghaibi wash shahhaadati fata'aalaa 'ammaa yushrikoon",
        translation: "(Dialah Tuhan) yang mengetahui semua yang gaib dan semua yang tampak. Mahatinggi (Allah) dari apa yang mereka persekutukan.",
        shortTafsir: "Dialah Tuhan yang mengetahui semua yang gaib dari pandangan manusia dan semua yang tampak. Mahatinggi Allah dari apa yang mereka persekutukan seperti kepercayaan kaum musyrik tersebut.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2765",
      ),
      Ayah(
        numberInSurah: 93,
        numberInQuran: 2766,
        juz: 18,
        page: 348,
        arab: "\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Qur Rabbi immmaa turiyannee maa yoo'adoon",
        translation: "Katakanlah (Muhammad), \u201cYa Tuhanku, seandainya Engkau hendak memperlihatkan kepadaku apa (azab) yang diancamkan kepada mereka,",
        shortTafsir: "Kezaliman kaum musyrik dengan menolak kebenaran itu meng-undang datangnya siksa Allah. Allah lalu mengajari Nabi doa berikut.\u00a0Katakanlah,\u00a0wahai Nabi Muhammad, \u201cYa Tuhanku, seandainya Engkau hendak memperlihatkan kepadaku\u00a0sebelum kematianku azab\u00a0yang diancamkan kepada mereka, Ya Tuhanku, maka janganlah Engkau jadikan aku\u00a0termasuk\u00a0dalam golongan orang-orang zalim, dan jauhkanlah aku dari mereka.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2766",
      ),
      Ayah(
        numberInSurah: 94,
        numberInQuran: 2767,
        juz: 18,
        page: 348,
        arab: "\u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Rabbi falaa taj'alnee fil qawmiz zaalimeen",
        translation: "Ya Tuhanku, maka janganlah Engkau jadikan aku dalam golongan orang-orang zalim.\u201d",
        shortTafsir: "Kezaliman kaum musyrik dengan menolak kebenaran itu meng-undang datangnya siksa Allah. Allah lalu mengajari Nabi doa berikut.\u00a0Katakanlah,\u00a0wahai Nabi Muhammad, \u201cYa Tuhanku, seandainya Engkau hendak memperlihatkan kepadaku\u00a0sebelum kematianku azab\u00a0yang diancamkan kepada mereka, Ya Tuhanku, maka janganlah Engkau jadikan aku\u00a0termasuk\u00a0dalam golongan orang-orang zalim, dan jauhkanlah aku dari mereka.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2767",
      ),
      Ayah(
        numberInSurah: 95,
        numberInQuran: 2768,
        juz: 18,
        page: 348,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646 \u0646\u0651\u064f\u0631\u0650\u064a\u064e\u0643\u064e \u0645\u064e\u0627 \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa innaa 'alaaa an nuriyaka maa na'iduhum laqaadiroon",
        translation: "Dan sungguh, Kami kuasa untuk memperlihatkan kepadamu (Muhammad) apa yang Kami ancamkan kepada mereka.",
        shortTafsir: "Allah mengajari Nabi doa tersebut bukan karena Allah tidak kuasa menjatuhkan siksa saat Nabi masih hidup, namun Dia hanya menundanya sebagaimana ditegaskan dalam ayat ini. Dan sungguh, Kami benar-benar kuasa untuk memperlihatkan kepadamu, wahai Nabi Muhammad, apa yang Kami ancamkan kepada mereka. Karena itu, janganlah engkau berduka atas pendustaan mereka kepadamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2768",
      ),
      Ayah(
        numberInSurah: 96,
        numberInQuran: 2769,
        juz: 18,
        page: 348,
        arab: "\u0627\u062f\u0652\u0641\u064e\u0639\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u06da \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",
        transliteration: "Idfa' billate hiya ahsanus saiyi'ah; nahnu a'lamu bimaa yasifoon",
        translation: "Tolaklah perbuatan buruk mereka dengan (cara) yang lebih baik, Kami lebih mengetahui apa yang mereka sifatkan (kepada Allah).",
        shortTafsir: "Allah dalam ayat ini mengajari Nabi cara menghadapi pendustaan kaum musyrik.\u00a0Tolaklah perbuatan buruk mereka dengan\u00a0cara\u00a0yang lebih baik,\u00a0antara lain dengan tetap berbuat baik kepada mereka semampumu, memaafkan kesalahan mereka yang berkaitan dengan hak pribadimu, atau tidak menanggapi ejekan dan cemoohan mereka.\u00a0Kami lebih mengetahui apa yang mereka sifatkan\u00a0kepada Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2769",
      ),
      Ayah(
        numberInSurah: 97,
        numberInQuran: 2770,
        juz: 18,
        page: 348,
        arab: "\u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0632\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650",
        transliteration: "Wa qur Rabbi a'oozu bika min hamazaatish Shayaateen",
        translation: "Dan katakanlah, \u201cYa Tuhanku, aku berlindung kepada Engkau dari bisikan-bisikan setan,",
        shortTafsir: "Dan katakanlah, wahai Nabi Muhammad, \u201cYa Tuhanku, aku berlindung kepada Engkau dari bisikan-bisikan setan, dan aku berlindung pula kepada Engkau ya Tuhanku, agar mereka tidak mendekati aku dalam segala aktivitasku.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2770",
      ),
      Ayah(
        numberInSurah: 98,
        numberInQuran: 2771,
        juz: 18,
        page: 348,
        arab: "\u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646 \u064a\u064e\u062d\u0652\u0636\u064f\u0631\u064f\u0648\u0646\u0650",
        transliteration: "Wa a'oozu bika Rabbi ai-yahduroon",
        translation: "dan aku berlindung (pula) kepada Engkau ya Tuhanku, agar mereka tidak mendekati aku.\u201d",
        shortTafsir: "Dan katakanlah, wahai Nabi Muhammad, \u201cYa Tuhanku, aku berlindung kepada Engkau dari bisikan-bisikan setan, dan aku berlindung\u00a0pula\u00a0kepada Engkau ya Tuhanku, agar mereka tidak mendekati aku\u00a0dalam segala aktivitasku.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2771",
      ),
      Ayah(
        numberInSurah: 99,
        numberInQuran: 2772,
        juz: 18,
        page: 348,
        arab: "\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Hattaaa izaa jaaa'a ahada humul mawtu qaala Rabbir ji'oon",
        translation: "(Demikianlah keadaan orang-orang kafir itu), hingga apabila datang kematian kepada seseorang dari mereka, dia berkata, \u201cYa Tuhanku, kembalikanlah aku (ke dunia),",
        shortTafsir: "Orang-orang kafir itu akan terus membangkang, hingga apabila datang kematian kepada seseorang dari mereka untuk mengakhiri kehi-dupannya di dunia dan menghentikan kenikmatan yang dirasakannya, hingga pada akhirnya ia melihat siksa yang akan diterimanya, dia berkata, \u201cYa Tuhanku, kembalikanlah aku ke dunia agar aku dapat berbuat kebajikan yang telah aku tinggalkan.\u201d Sekali-kali tidak! Allah tidak akan memenuhi permohonan mereka karena Allah tahu bahwa mereka tidak akan menepati janji. Sesungguhnya itu adalah dalih yang diucapkannya saja. Dan di hadapan serta di belakang mereka ada barzakh, yaitu dinding pemisah antara kehidupan dunia dan akhirat, yang menghalangi mereka kembali ke dunia sampai pada hari mereka dibangkitkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2772",
      ),
      Ayah(
        numberInSurah: 100,
        numberInQuran: 2773,
        juz: 18,
        page: 348,
        arab: "\u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f \u06da \u0643\u064e\u0644\u0651\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0626\u0650\u0644\u064f\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650\u0645 \u0628\u064e\u0631\u0652\u0632\u064e\u062e\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",
        transliteration: "La'alleee a'malu saalihan feemaa taraktu kallaa; innahaa kalimatun huwa qaaa'iluhaa wa minw waraaa'him barzakhun ilaa Yawmi yub'asoon",
        translation: "agar aku dapat berbuat kebajikan yang telah aku tinggalkan.\u201d Sekali-kali tidak! Sesungguhnya itu adalah dalih yang diucapkannya saja. Dan di hadapan mereka ada barzakh sampai pada hari mereka dibangkitkan.",
        shortTafsir: "Orang-orang kafir itu akan terus membangkang,\u00a0hingga apabila datang kematian kepada seseorang dari mereka\u00a0untuk mengakhiri kehi-dupannya di dunia dan menghentikan kenikmatan yang dirasakannya, hingga pada akhirnya ia melihat siksa yang akan diterimanya,\u00a0dia berkata, \u201cYa Tuhanku, kembalikanlah aku\u00a0ke dunia\u00a0agar aku dapat berbuat kebajikan yang telah aku tinggalkan.\u201d Sekali-kali tidak!\u00a0Allah tidak akan memenuhi permohonan mereka karena Allah tahu bahwa mereka tidak akan menepati janji.\u00a0Sesungguhnya itu adalah dalih yang diucapkannya saja. Dan di hadapan\u00a0serta di belakang\u00a0mereka ada barzakh, yaitu dinding pemisah antara kehidupan dunia dan akhirat, yang menghalangi mereka kembali ke dunia\u00a0sampai pada hari mereka dibangkitkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2773",
      ),
      Ayah(
        numberInSurah: 101,
        numberInQuran: 2774,
        juz: 18,
        page: 348,
        arab: "\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0633\u064e\u0627\u0628\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Fa izaa nufikha fis Soori falaaa ansaaba bainahum yawma'izinw wa laa yatasaaa'aloon",
        translation: "Apabila sangkakala ditiup maka tidak ada lagi pertalian keluarga di antara mereka pada hari itu (hari Kiamat), dan tidak (pula) mereka saling bertanya.",
        shortTafsir: "Usai menjelaskan alam barzakh hingga hari Kebangkitan, Allah lalu memberi uraian tentang peristiwa hari Kebangkitan itu. Apabila sangkakala ditiup dengan tiupan pertama maka semua yang bernyawa segera mati, dan dalam tiupan kedua semua dibangkitkan, maka setiap orang akan menghadap Tuhan secara sendiri-sendiri (Lihat juga: Surah Maryam/19: 95); tidak ada lagi pertalian keluarga di antara mereka pada hari itu, dan tidak pula mereka saling bertanya. Mereka sibuk dengan urusan masing-masing dan diliputi ketakutan yang begitu mencekam.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2774",
      ),
      Ayah(
        numberInSurah: 102,
        numberInQuran: 2775,
        juz: 18,
        page: 348,
        arab: "\u0641\u064e\u0645\u064e\u0646 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",
        transliteration: "Faman saqulat mawaazee nuhoo fa ulaaa'ika humul muflihoon",
        translation: "Barangsiapa berat timbangan (kebaikan)nya, maka mereka itulah orang-orang yang beruntung.",
        shortTafsir: "Di hadapan Allah setiap individu akan diperiksa dan ditimbang amalnya, maka\u00a0barangsiapa berat timbangan\u00a0kebaikan-nya, mereka itulah orang-orang yang beruntung. Dan\u00a0sebaliknya,\u00a0barang siapa ringan timbangan\u00a0kebaikan-nya, maka mereka itulah orang-orang yang merugikan dirinya sendiri\u00a0karena gagal meraih keberuntungan dan membuat\u00a0mereka kekal di dalam neraka Jahanam. Wajah mereka, demikian juga anggota tubuh yang lain,\u00a0dibakar api neraka, dan mereka di neraka dalam keadaan muram dengan bibir yang cacat\u00a0sehingga kondisi mereka amat miris.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2775",
      ),
      Ayah(
        numberInSurah: 103,
        numberInQuran: 2776,
        juz: 18,
        page: 348,
        arab: "\u0648\u064e\u0645\u064e\u0646\u0652 \u062e\u064e\u0641\u0651\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Wa man khaffat mawaa zeenuhoo fa ulaaa'ikal lazeena khasiroon anfusahum fee Jahannnama khaalidoon",
        translation: "Dan barang siapa ringan timbangan (kebaikan)nya, maka mereka itulah orang-orang yang merugikan dirinya sendiri, mereka kekal di dalam neraka Jahanam",
        shortTafsir: "Di hadapan Allah setiap individu akan diperiksa dan ditimbang amalnya, maka\u00a0barangsiapa berat timbangan\u00a0kebaikan-nya, mereka itulah orang-orang yang beruntung. Dan\u00a0sebaliknya,\u00a0barang siapa ringan timbangan\u00a0kebaikan-nya, maka mereka itulah orang-orang yang merugikan dirinya sendiri\u00a0karena gagal meraih keberuntungan dan membuat\u00a0mereka kekal di dalam neraka Jahanam. Wajah mereka, demikian juga anggota tubuh yang lain,\u00a0dibakar api neraka, dan mereka di neraka dalam keadaan muram dengan bibir yang cacat\u00a0sehingga kondisi mereka amat miris.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2776",
      ),
      Ayah(
        numberInSurah: 104,
        numberInQuran: 2777,
        juz: 18,
        page: 348,
        arab: "\u062a\u064e\u0644\u0652\u0641\u064e\u062d\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0627\u0644\u0650\u062d\u064f\u0648\u0646\u064e",
        transliteration: "Talfahu wujoohahumun Naaru wa hum feehaa kaalihood",
        translation: "Wajah mereka dibakar api neraka, dan mereka di neraka dalam keadaan muram dengan bibir yang cacat.",
        shortTafsir: "Di hadapan Allah setiap individu akan diperiksa dan ditimbang amalnya, maka\u00a0barangsiapa berat timbangan\u00a0kebaikan-nya, mereka itulah orang-orang yang beruntung. Dan\u00a0sebaliknya,\u00a0barang siapa ringan timbangan\u00a0kebaikan-nya, maka mereka itulah orang-orang yang merugikan dirinya sendiri\u00a0karena gagal meraih keberuntungan dan membuat\u00a0mereka kekal di dalam neraka Jahanam. Wajah mereka, demikian juga anggota tubuh yang lain,\u00a0dibakar api neraka, dan mereka di neraka dalam keadaan muram dengan bibir yang cacat\u00a0sehingga kondisi mereka amat miris.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2777",
      ),
      Ayah(
        numberInSurah: 105,
        numberInQuran: 2778,
        juz: 18,
        page: 349,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Alam takun Aayaatee tutlaa 'alaikum fakuntum bihaa tukazziboon",
        translation: "Bukankah ayat-ayat-Ku telah dibacakan kepadamu, tetapi kamu selalu mendustakannya?",
        shortTafsir: "Seiring dengan siksa lahiriah itu, mereka juga mendapat kecaman dari Allah yang membuat batin mereka merana. Kepada mereka dikatakan, \u201cBukankah ayat-ayat-Ku telah dibacakan kepadamu, tetapi kamu selalu mendustakannya?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2778",
      ),
      Ayah(
        numberInSurah: 106,
        numberInQuran: 2779,
        juz: 18,
        page: 349,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0634\u0650\u0642\u0652\u0648\u064e\u062a\u064f\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0636\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",
        transliteration: "Qaaloo Rabbanaa ghalabat 'alainaa shiqwatunaa wa kunnaa qawman daaalleen",
        translation: "Mereka berkata, \u201cYa Tuhan kami, kami telah dikuasai oleh kejahatan kami, dan kami adalah orang-orang yang sesat.",
        shortTafsir: "Menjawab pertanyaan itu,\u00a0mereka berkata\u00a0dengan penuh penyesalan, \u201cYa Tuhan kami, kami telah dikuasai oleh kejahatan kami. Hawa nafsu telah menjerumuskan kami ke dalam kedurhakaan sehingga membuat kami menderita,\u00a0dan kami\u00a0di dunia dulu\u00a0adalah orang-orang yang sesat.\u201d Dengan pengakuan dan penyesalan itu mereka berharap ampunan dan keringanan siksa. Mereka pun memohon, \u201cYa Tuhan kami, keluarkanlah kami darinya, yaitu dari siksa neraka dan kesengsaraan ini, kembalikanlah kami ke dunia.\u00a0Jika\u00a0Engkau memperkenankan permohonan kami ini lalu setelah itu\u00a0kami masih juga kembali\u00a0kepada kekafiran dan kedurhakaan maka\u00a0sungguh, kami adalah orang-orang yang zalim.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2779",
      ),
      Ayah(
        numberInSurah: 107,
        numberInQuran: 2780,
        juz: 18,
        page: 349,
        arab: "\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064f\u062f\u0652\u0646\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Rabbanaa akhrijnaa minhaa fa in 'udnaa fa innaa zaalimoon",
        translation: "Ya Tuhan kami, keluarkanlah kami darinya (kembalikanlah kami ke dunia), jika kami masih juga kembali (kepada kekafiran), sungguh, kami adalah orang-orang yang zalim.\u201d",
        shortTafsir: "Menjawab pertanyaan itu,\u00a0mereka berkata\u00a0dengan penuh penyesalan, \u201cYa Tuhan kami, kami telah dikuasai oleh kejahatan kami. Hawa nafsu telah menjerumuskan kami ke dalam kedurhakaan sehingga membuat kami menderita,\u00a0dan kami\u00a0di dunia dulu\u00a0adalah orang-orang yang sesat.\u201d Dengan pengakuan dan penyesalan itu mereka berharap ampunan dan keringanan siksa. Mereka pun memohon, \u201cYa Tuhan kami, keluarkanlah kami darinya, yaitu dari siksa neraka dan kesengsaraan ini, kembalikanlah kami ke dunia.\u00a0Jika\u00a0Engkau memperkenankan permohonan kami ini lalu setelah itu\u00a0kami masih juga kembali\u00a0kepada kekafiran dan kedurhakaan maka\u00a0sungguh, kami adalah orang-orang yang zalim.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2780",
      ),
      Ayah(
        numberInSurah: 108,
        numberInQuran: 2781,
        juz: 18,
        page: 349,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0627\u062e\u0652\u0633\u064e\u0626\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u0650",
        transliteration: "Qaalakh sa'oo feehaa wa laa tukallimoon",
        translation: "Dia (Allah) berfirman, \u201cTinggallah dengan hina di dalamnya, dan janganlah kamu berbicara dengan Aku.\u201d",
        shortTafsir: "Mendengar permohonan para pendurhaka, Dia berfirman, \u201cTinggallah dengan hina di dalamnya, yakni neraka, dan janganlah kamu berbicara dengan Aku karena tidak ada lagi kesempatan untuk tawar-menawar. Kalian, wahai para pendurhaka, tidak pula akan memperoleh kehormatan untuk berdialog dengan-Ku.\u201d Mengingatkan kembali salah satu kedurhakaan mereka, Allah berfirman, \u201cSesungguhnya ada segolongan dari hamba-hamba-Ku berdoa, \u201cYa Tuhan kami, kami telah ber-iman, maka ampunilah kami dan berilah kami rahmat, Engkau adalah pemberi rahmat yang terbaik.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2781",
      ),
      Ayah(
        numberInSurah: 109,
        numberInQuran: 2782,
        juz: 18,
        page: 349,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0651\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Innahoo kaana fareequm min 'ibaadee yaqooloona Rabbanaaa aamannaa faghfir lanaa warhamnaa wa Anta khairur raahimeen",
        translation: "Sesungguhnya ada segolongan dari hamba-hamba-Ku berdoa, \u201cYa Tuhan kami, kami telah beriman, maka ampunilah kami dan berilah kami rahmat, Engkau adalah pemberi rahmat yang terbaik.\u201d",
        shortTafsir: "Mendengar permohonan para pendurhaka,\u00a0Dia berfirman, \u201cTinggallah dengan hina di dalamnya, yakni neraka,\u00a0dan janganlah kamu berbicara dengan Aku\u00a0karena tidak ada lagi kesempatan untuk tawar-menawar. Kalian, wahai para pendurhaka, tidak pula akan memperoleh kehormatan untuk berdialog dengan-Ku.\u201d Mengingatkan kembali salah satu kedurhakaan mereka, Allah berfirman, \u201cSesungguhnya ada segolongan dari hamba-hamba-Ku berdoa, \u201cYa Tuhan kami, kami telah ber-iman, maka ampunilah kami dan berilah kami rahmat, Engkau adalah pemberi rahmat yang terbaik.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2782",
      ),
      Ayah(
        numberInSurah: 110,
        numberInQuran: 2783,
        juz: 18,
        page: 349,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0633\u0650\u062e\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064e\u0646\u0633\u064e\u0648\u0652\u0643\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u064a \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e",
        transliteration: "Fattakhaztumoohum sikhriyyan hattaaa ansawkum zikree wa kuntum minhum tadhakoon",
        translation: "Lalu kamu jadikan mereka buah ejekan, sehingga kamu lupa mengingat Aku, dan kamu (selalu) menertawakan mereka,",
        shortTafsir: "Kamu, wahai para pendurhaka, mendengar orang-orang mukmin tulus berdoa demikian, lalu kamu jadikan mereka buah ejekan. Begitu sibuk kamu mengejek mereka sehingga kamu lupa mengingat Aku, dan kamu pun selalu menghina dan menertawakan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2783",
