        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0632\u064e\u064a\u0652\u062a\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0626\u0650\u0632\u064f\u0648\u0646\u064e",
